def can_order(stock, name):
    if stock[name] > 0:
        return True
    return False

stock = {"coffee": 3, "latte": 0, "cake": 2}
for o in ["coffee", "latte", "cake"]:
    if can_order(stock, o):
        print(o, "주문 받았어요")
    else:
        print(o, "품절이에요")

def grade(score):
    if score >= 90:
        return "A"
    elif score >= 80:
        return "B"
    elif score >= 70:
        return "C"
    return "F"

scores = [["kim", 92], ["lee", 78], ["park", 85], ["choi", 59]]
for name, score in scores:
    print(f"{name:<5}{score:>3}  {grade(score)}")

def discount_rate(total):
    if total >= 20000:
        return 10
    elif total >= 10000:
        return 5
    return 0

def pay(total):
    rate = discount_rate(total)
    sale = total * rate // 100
    return total - sale

print(pay(8000))
print(pay(15500))
print(pay(22000))
